// Quiz logic is independent from rendering and account state.
export function shuffle(items,seed){const out=[...items];let x=seed>>>0;const rand=()=>{x=(x+0x6D2B79F5)>>>0;let t=x;t=Math.imul(t^(t>>>15),t|1);t^=t+Math.imul(t^(t>>>7),t|61);return ((t^(t>>>14))>>>0)/4294967296};for(let i=out.length-1;i>0;i--){const j=Math.floor(rand()*(i+1));[out[i],out[j]]=[out[j],out[i]]}return out}
export const emptyLearning=()=>({version:1,dayCompleted:[],dayProgress:{},attempts:[],session:null});
export function grade(q,answer){return q.type==='numeric'?typeof answer==='number'&&Number.isFinite(answer)&&Math.abs(answer-q.answer)<=q.tolerance+1e-9:answer===q.correct}
export function topicStats(bank,attempts){const first=new Map(),latest=new Map(),everWrong=new Set();for(const a of attempts){if(!first.has(a.questionId))first.set(a.questionId,a);latest.set(a.questionId,a);if(!a.correct)everWrong.add(a.questionId)}const byTopic=Object.fromEntries([...new Set(bank.map(q=>q.topic))].map(t=>{const ids=new Set(bank.filter(q=>q.topic===t).map(q=>q.id)),xs=[...first.values()].filter(a=>ids.has(a.questionId));return [t,{seen:xs.length,correct:xs.filter(a=>a.correct).length}]}));return {first:[...first.values()],latest,everWrong,byTopic,wrongIds:[...latest.values()].filter(a=>!a.correct).map(a=>a.questionId),reviewed:[...everWrong].filter(id=>latest.get(id)?.correct).length}}
export function startSession(bank,mode,topic,attempts,seed,id){const stats=topicStats(bank,attempts),eligible=bank.filter(q=>(mode!=='topic'||q.topic===topic)&&(mode!=='review'||stats.wrongIds.includes(q.id)));const count=mode==='mixed'?20:10;return {id,mode,topic:topic||null,seed,ids:shuffle(eligible.map(q=>q.id),seed).slice(0,count),index:0,answers:{},hinted:{},submitted:false}}
export function recordAnswer(learning,bank,answer,at){const s=learning.session,q=bank.find(q=>q.id===s?.ids[s.index]);if(!q)throw Error('No active question');if(s.answers[q.id])throw Error('Already answered');if(q.type==='numeric'&&(typeof answer!=='number'||!Number.isFinite(answer)))throw Error('Enter a finite number');if(q.type!=='numeric'&&!q.options.some(o=>o.id===answer))throw Error('Select an answer');const attempt={id:s.id+':'+q.id,sessionId:s.id,questionId:q.id,answer,correct:grade(q,answer),hinted:!!s.hinted[q.id],at};s.answers[q.id]=attempt;learning.attempts.push(attempt);return attempt}
export function choices(q,seed){return shuffle(q.options||[],seed+q.id.split('').reduce((a,c)=>a+c.charCodeAt(0),0))}

